import * as React from 'react'
import { UploadCloud, X, FileText, Loader2, Check, RefreshCw } from 'lucide-react'
import { cn } from '@/lib/utils'
import { useControllableState } from '@/components/ui/util'
export interface UploadFile {
  id: string
  file: File
  status: 'ready' | 'uploading' | 'done' | 'error'
  error?: string
  progress?: number
  preview?: string
}
export interface UploadProps {
  label?: string
  accept?: string
  multiple?: boolean
  maxSize?: number
  maxCount?: number
  disabled?: boolean
  onFilesChange?: (files: File[]) => void
  customRequest?: (
    file: File,
    signal: AbortSignal,
    onProgress: (percent: number) => void,
  ) => Promise<void>
  directory?: boolean
  showThumbnails?: boolean
  className?: string
  fileList?: UploadFile[]
  defaultFileList?: UploadFile[]
  onFileListChange?: (files: UploadFile[]) => void
  beforeUpload?: (file: File) => File | false | Promise<File | false>
  paste?: boolean
}
/**
 * Manages local file selection, previews, and optional application-provided upload requests. Aborts active requests and releases object URLs on cleanup.
 */
export function Upload({
  label,
  accept,
  multiple = true,
  maxSize = 10 * 1024 * 1024,
  maxCount = 10,
  disabled,
  onFilesChange,
  customRequest,
  className,
  directory,
  showThumbnails = true,
  fileList,
  defaultFileList = [],
  onFileListChange,
  beforeUpload,
  paste = true,
}: UploadProps) {
  const [files, setFiles] = useControllableState<UploadFile[]>({
    value: fileList,
    defaultValue: defaultFileList,
    onChange: onFileListChange,
  })
  const [error, setError] = React.useState('')
  const [drag, setDrag] = React.useState(false)
  const input = React.useRef<HTMLInputElement>(null)
  const requests = React.useRef(new Map<string, AbortController>())
  const previews = React.useRef(new Map<string, string>())
  React.useEffect(
    () => () => {
      requests.current.forEach((c) => c.abort())
      previews.current.forEach((url) => URL.revokeObjectURL(url))
    },
    [],
  )
  const start = (entry: UploadFile) => {
    if (!customRequest) return
    const controller = new AbortController()
    requests.current.set(entry.id, controller)
    setFiles((files) =>
      files.map((f) =>
        f.id === entry.id ? { ...f, status: 'uploading', error: undefined, progress: 0 } : f,
      ),
    )
    Promise.resolve()
      .then(() =>
        customRequest(entry.file, controller.signal, (percent) => {
          if (!controller.signal.aborted)
            setFiles((files) =>
              files.map((f) =>
                f.id === entry.id ? { ...f, progress: Math.max(0, Math.min(100, percent)) } : f,
              ),
            )
        }),
      )
      .then(() => {
        if (!controller.signal.aborted)
          setFiles((files) =>
            files.map((f) => (f.id === entry.id ? { ...f, status: 'done', progress: 100 } : f)),
          )
      })
      .catch((error) => {
        if (!controller.signal.aborted)
          setFiles((files) =>
            files.map((f) =>
              f.id === entry.id
                ? {
                    ...f,
                    status: 'error',
                    error: error instanceof Error ? error.message : String(error),
                  }
                : f,
            ),
          )
      })
      .finally(() => requests.current.delete(entry.id))
  }
  const add = async (incoming: File[]) => {
    if (disabled) return
    setError('')
    const available = (multiple ? maxCount : 1) - files.length
    const accepted: UploadFile[] = []
    for (let file of incoming) {
      if (beforeUpload) {
        try {
          const result = await beforeUpload(file)
          if (result === false) continue
          file = result
        } catch (error) {
          setError(String(error))
          continue
        }
      }
      const types = accept?.split(',').map((t) => t.trim().toLowerCase())
      const valid =
        !types ||
        types.some((t) =>
          t.startsWith('.')
            ? file.name.toLowerCase().endsWith(t)
            : t.endsWith('/*')
              ? file.type.startsWith(t.slice(0, -1))
              : file.type === t,
        )
      if (file.size > maxSize) {
        setError(`${file.name} exceeds ${(maxSize / 1024 / 1024).toFixed(0)} MB.`)
        continue
      }
      if (!valid) {
        setError(`${file.name} is not an accepted file type.`)
        continue
      }
      if (accepted.length >= available) {
        setError(`Choose at most ${multiple ? maxCount : 1} files.`)
        break
      }
      const id = crypto.randomUUID(),
        preview =
          showThumbnails && file.type.startsWith('image/') ? URL.createObjectURL(file) : undefined
      if (preview) previews.current.set(id, preview)
      accepted.push({
        id,
        file,
        preview,
        status: customRequest ? 'uploading' : 'ready',
      })
    }
    const next = [...files, ...accepted]
    setFiles(next)
    onFilesChange?.(next.map((f) => f.file))
    accepted.forEach(start)
  }
  return (
    <div
      className={cn('w-full max-w-lg', className)}
      onPaste={(e) => {
        if (paste && e.clipboardData.files.length) {
          e.preventDefault()
          void add(Array.from(e.clipboardData.files))
        }
      }}
    >
      <button
        type="button"
        aria-label={
          label
            ? `${label}: Click to upload or drag and drop ${accept || 'Any file type'} · up to ${maxSize / 1024 / 1024} MB`
            : undefined
        }
        disabled={disabled}
        onClick={() => input.current?.click()}
        onDragOver={(e) => {
          e.preventDefault()
          setDrag(true)
        }}
        onDragLeave={() => setDrag(false)}
        onDrop={(e) => {
          e.preventDefault()
          setDrag(false)
          add(Array.from(e.dataTransfer.files))
        }}
        className={cn(
          'flex w-full flex-col items-center gap-2 rounded-xl border border-dashed p-8 text-sm transition hover:border-primary hover:bg-primary/5 disabled:opacity-50',
          drag && 'border-primary bg-primary/5',
        )}
      >
        <UploadCloud className="mb-2 size-8 text-primary" />
        <span className="font-medium">Click to upload or drag and drop</span>
        <span className="text-xs text-muted-foreground">
          {accept || 'Any file type'} · up to {maxSize / 1024 / 1024} MB
        </span>
      </button>
      <input
        ref={input}
        className="hidden"
        type="file"
        accept={accept}
        multiple={multiple}
        {...(directory ? { webkitdirectory: '' } : {})}
        disabled={disabled}
        aria-label={label ?? 'Choose files'}
        onChange={(e) => {
          add(Array.from(e.target.files ?? []))
          e.target.value = ''
        }}
      />
      {error && (
        <p role="alert" className="mt-2 text-xs text-destructive">
          {error}
        </p>
      )}
      <ul className="mt-3 space-y-2">
        {files.map((f) => (
          <li key={f.id} className="flex items-center gap-2 rounded-md border p-2.5 text-sm">
            {f.preview ? (
              <img
                src={f.preview}
                alt={f.file.name}
                className="size-10 shrink-0 rounded object-cover"
              />
            ) : (
              <FileText size={16} />
            )}
            <span className="min-w-0 flex-1 truncate">
              {f.file.name}
              <small className="ml-2 text-muted-foreground">
                {(f.file.size / 1024).toFixed(1)} KB
              </small>
              {f.status === 'error' && (
                <span className="block text-xs text-destructive">{f.error}</span>
              )}
              {f.status === 'uploading' && (
                <span className="mt-2 block h-1 overflow-hidden rounded-full bg-muted">
                  <span
                    className="block h-full bg-primary transition-[width]"
                    style={{ width: `${f.progress ?? 0}%` }}
                  />
                </span>
              )}
            </span>
            {f.status === 'uploading' ? (
              <Loader2 className="size-4 animate-spin" />
            ) : f.status === 'done' ? (
              <Check className="size-4 text-emerald-600" />
            ) : null}
            {f.status === 'error' && (
              <button
                type="button"
                disabled={disabled}
                aria-label={`Retry ${f.file.name}`}
                onClick={() => start(f)}
              >
                <RefreshCw size={14} />
              </button>
            )}
            <button
              type="button"
              aria-label={`Remove ${f.file.name}`}
              onClick={() => {
                requests.current.get(f.id)?.abort()
                const preview = previews.current.get(f.id)
                if (preview) {
                  URL.revokeObjectURL(preview)
                  previews.current.delete(f.id)
                }
                const next = files.filter((v) => v.id !== f.id)
                setFiles(next)
                onFilesChange?.(next.map((v) => v.file))
              }}
            >
              <X size={14} />
            </button>
          </li>
        ))}
      </ul>
    </div>
  )
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import { breakpoints, type Breakpoint } from '@/lib/responsive'
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [internal, setInternal] = React.useState(defaultValue)
  const current = value === undefined ? internal : value
  const currentRef = React.useRef(current),
    valueRef = React.useRef(value),
    changeRef = React.useRef(onChange)
  currentRef.current = current
  valueRef.current = value
  changeRef.current = onChange
  const set = React.useCallback((next: T | ((previous: T) => T)) => {
    const previous = currentRef.current
    const result = typeof next === 'function' ? (next as (previous: T) => T)(previous) : next
    if (Object.is(previous, result)) return
    currentRef.current = result
    if (valueRef.current === undefined) setInternal(result)
    changeRef.current?.(result)
  }, [])
  return [current, set] as const
}
export function useMediaQuery(query: string) {
  const [matches, setMatches] = React.useState(
    () => typeof window !== 'undefined' && window.matchMedia(query).matches,
  )
  React.useEffect(() => {
    const m = window.matchMedia(query)
    const update = () => setMatches(m.matches)
    update()
    m.addEventListener('change', update)
    return () => m.removeEventListener('change', update)
  }, [query])
  return matches
}
export function useDebouncedValue<T>(value: T, delay = 250) {
  const [debounced, set] = React.useState(value)
  React.useEffect(() => {
    const id = setTimeout(() => set(value), delay)
    return () => clearTimeout(id)
  }, [value, delay])
  return debounced
}
export async function copyToClipboard(text: string) {
  await navigator.clipboard.writeText(text)
}
export function useBreakpoints() {
  const [width, setWidth] = React.useState(() =>
    typeof window === 'undefined' ? 0 : window.innerWidth,
  )
  React.useEffect(() => {
    const update = () => setWidth(window.innerWidth)
    window.addEventListener('resize', update)
    return () => window.removeEventListener('resize', update)
  }, [])
  return Object.fromEntries(
    Object.entries(breakpoints).map(([key, min]) => [key, width >= min]),
  ) as Record<Breakpoint, boolean>
}

import type { CSSProperties } from 'react'
export const breakpoints = { xs: 0, sm: 640, md: 768, lg: 1024, xl: 1280, '2xl': 1536 } as const
export type Breakpoint = keyof typeof breakpoints
export type Responsive<T> = T | Partial<Record<Breakpoint, T>>
export function responsiveStyle<T>(value: Responsive<T> | undefined, name: string): CSSProperties {
  if (value === undefined) return {}
  const values = typeof value === 'object' && value !== null ? value : { xs: value }
  return Object.fromEntries(
    Object.entries(values).map(([key, v]) => [`--${name}-${key}`, v]),
  ) as CSSProperties
}
export const responsiveCSS = Object.entries(breakpoints)
  .map(([, min], index) => {
    const fallback = (name: string, initial: string) =>
      Object.keys(breakpoints)
        .slice(0, index + 1)
        .reduce((result, key) => `var(--${name}-${key},${result})`, initial)
    return `@media(min-width:${min}px){.ergon-col{width:calc(${fallback('span', '24')} / 24 * 100%);margin-inline-start:calc(${fallback('offset', '0')} / 24 * 100%);order:${fallback('order', '0')}}.ergon-flex{gap:${fallback('gap', '12px')};flex-direction:${fallback('direction', 'row')}}}`
  })
  .join('')

import * as React from 'react'
import { Upload, type UploadProps } from '@/components/ui/upload'
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
export function ImageCropUpload({
  aspect = 1,
  beforeUpload,
  ...props
}: UploadProps & { aspect?: number }) {
  const [crop, setCrop] = React.useState<{
      file: File
      url: string
      width: number
      height: number
      resolve: (file: File | false) => void
    }>(),
    [x, setX] = React.useState(50),
    [y, setY] = React.useState(50),
    [scale, setScale] = React.useState(100),
    [error, setError] = React.useState('')
  const image = React.useRef<HTMLImageElement>(null),
    latest = React.useRef(crop)
  latest.current = crop
  React.useEffect(
    () => () => {
      if (latest.current) {
        latest.current.resolve(false)
        URL.revokeObjectURL(latest.current.url)
      }
    },
    [],
  )
  const close = (file: File | false) => {
    if (crop) {
      crop.resolve(file)
      URL.revokeObjectURL(crop.url)
      setCrop(undefined)
    }
  }
  const before = async (file: File) => {
    const transformed = (await beforeUpload?.(file)) ?? file
    if (transformed === false || !transformed.type.startsWith('image/')) return transformed
    const url = URL.createObjectURL(transformed),
      bitmap = await createImageBitmap(transformed),
      width = bitmap.width,
      height = bitmap.height
    bitmap.close()
    setX(50)
    setY(50)
    setScale(100)
    return new Promise<File | false>((resolve) =>
      setCrop({ file: transformed, url, width, height, resolve }),
    )
  }
  const width = crop ? (Math.min(crop.width, crop.height * aspect) * scale) / 100 : 0,
    height = width / aspect,
    left = crop ? ((crop.width - width) * x) / 100 : 0,
    top = crop ? ((crop.height - height) * y) / 100 : 0
  return (
    <>
      <Upload {...props} disabled={props.disabled || !!crop} beforeUpload={before} />
      <Dialog
        open={!!crop}
        onOpenChange={(open) => {
          if (!open) close(false)
        }}
      >
        <DialogContent>
          <DialogTitle>Crop image</DialogTitle>
          <DialogDescription>Choose the area to include in your upload.</DialogDescription>
          {crop && (
            <div
              className="relative mx-auto overflow-hidden rounded-lg"
              style={{ maxWidth: Math.min(450, (288 * crop.width) / crop.height) }}
            >
              <img
                ref={image}
                src={crop.url}
                alt="Crop preview"
                className="max-h-72 w-full object-contain"
              />
              <div
                aria-hidden
                className="pointer-events-none absolute border-2 border-white shadow-[0_0_0_999px_#0006]"
                style={{
                  width: `${(width / crop.width) * 100}%`,
                  height: `${(height / crop.height) * 100}%`,
                  left: `${(left / crop.width) * 100}%`,
                  top: `${(top / crop.height) * 100}%`,
                }}
              />
            </div>
          )}
          {[
            ['Horizontal position', x, setX],
            ['Vertical position', y, setY],
            ['Crop size', scale, setScale],
          ].map(([label, value, set]) => (
            <label key={String(label)} className="flex items-center gap-3 text-xs">
              <span className="w-28">{String(label)}</span>
              <input
                aria-label={String(label)}
                type="range"
                min={label === 'Crop size' ? 10 : 0}
                max={100}
                value={value as number}
                onChange={(event) =>
                  (set as React.Dispatch<React.SetStateAction<number>>)(Number(event.target.value))
                }
                className="flex-1"
              />
            </label>
          ))}
          {error && (
            <p role="alert" className="text-xs text-destructive">
              {error}
            </p>
          )}
          <DialogFooter>
            <Button variant="ghost" onClick={() => close(false)}>
              Cancel
            </Button>
            <Button
              onClick={() => {
                try {
                  if (!crop || !image.current) return
                  const canvas = document.createElement('canvas')
                  canvas.width = width
                  canvas.height = height
                  canvas
                    .getContext('2d')!
                    .drawImage(image.current, left, top, width, height, 0, 0, width, height)
                  canvas.toBlob(
                    (blob) => {
                      if (!blob) {
                        setError('Could not crop this image')
                        return
                      }
                      close(new File([blob], crop.file.name, { type: blob.type }))
                    },
                    crop.file.type === 'image/png' ? 'image/png' : 'image/jpeg',
                    0.92,
                  )
                } catch (error) {
                  setError(String(error))
                }
              }}
            >
              Use crop
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  )
}

import { usePortalContainer } from '@/components/ui/config-provider'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { XIcon } from 'lucide-react'
import { Dialog as DialogPrimitive } from 'radix-ui'

import { Button } from '@/components/ui/button'

function Dialog({ ...props }: React.ComponentProps<typeof DialogPrimitive.Root>) {
  return <DialogPrimitive.Root data-slot="dialog" {...props} />
}

function DialogTrigger({ ...props }: React.ComponentProps<typeof DialogPrimitive.Trigger>) {
  return <DialogPrimitive.Trigger data-slot="dialog-trigger" {...props} />
}

function DialogPortal({ ...props }: React.ComponentProps<typeof DialogPrimitive.Portal>) {
  return (
    <DialogPrimitive.Portal container={usePortalContainer()} data-slot="dialog-portal" {...props} />
  )
}

function DialogClose({ ...props }: React.ComponentProps<typeof DialogPrimitive.Close>) {
  return <DialogPrimitive.Close data-slot="dialog-close" {...props} />
}

function DialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Overlay>) {
  return (
    <DialogPrimitive.Overlay
      data-slot="dialog-overlay"
      className={cn(
        'fixed inset-0 z-50 bg-black/50 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:animate-in data-[state=open]:fade-in-0',
        className,
      )}
      {...props}
    />
  )
}

function DialogContent({
  className,
  children,
  showCloseButton = true,
  draggable,
  resizable,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Content> & {
  showCloseButton?: boolean
  draggable?: boolean
  resizable?: boolean
}) {
  const [position, setPosition] = React.useState({ x: 0, y: 0 }),
    drag = React.useRef<{
      x: number
      y: number
      px: number
      py: number
      limitX: number
      limitY: number
    } | null>(null)
  return (
    <DialogPortal data-slot="dialog-portal">
      <DialogOverlay />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        className={cn(
          'fixed top-[50%] left-[50%] z-50 grid w-full max-w-[calc(100%-2rem)] translate-x-[-50%] translate-y-[-50%] gap-4 rounded-lg border bg-background p-6 shadow-lg duration-200 outline-none data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 sm:max-w-lg',
          className,
        )}
        {...props}
        style={{
          ...(draggable
            ? {
                transform: `translate(calc(-50% + ${position.x}px),calc(-50% + ${position.y}px))`,
                translate: 'none',
              }
            : {}),
          ...(resizable
            ? {
                resize: 'both',
                width: 'min(512px,calc(100vw - 32px))',
                overflow: 'auto',
                minWidth: 260,
                minHeight: 150,
                maxWidth: 'calc(100vw - 32px)',
                maxHeight: 'calc(100vh - 32px)',
              }
            : {}),
          ...props.style,
        }}
        onPointerDown={(event) => {
          props.onPointerDown?.(event)
          if (
            !draggable ||
            (event.target as HTMLElement).closest('button,input,textarea,select,a') ||
            !(event.target as HTMLElement).closest(
              '[data-slot="dialog-header"],[data-slot="dialog-title"]',
            )
          )
            return
          const bounds = event.currentTarget.getBoundingClientRect()
          drag.current = {
            x: event.clientX,
            y: event.clientY,
            px: position.x,
            py: position.y,
            limitX: Math.max(0, (innerWidth - bounds.width) / 2 - 16),
            limitY: Math.max(0, (innerHeight - bounds.height) / 2 - 16),
          }
          event.currentTarget.setPointerCapture(event.pointerId)
        }}
        onPointerMove={(event) => {
          props.onPointerMove?.(event)
          if (drag.current)
            setPosition({
              x: Math.max(
                -drag.current.limitX,
                Math.min(drag.current.limitX, drag.current.px + event.clientX - drag.current.x),
              ),
              y: Math.max(
                -drag.current.limitY,
                Math.min(drag.current.limitY, drag.current.py + event.clientY - drag.current.y),
              ),
            })
        }}
        onPointerUp={(event) => {
          drag.current = null
          props.onPointerUp?.(event)
        }}
        onLostPointerCapture={() => {
          drag.current = null
        }}
      >
        {children}
        {showCloseButton && (
          <DialogPrimitive.Close
            data-slot="dialog-close"
            className="absolute top-4 right-4 rounded-xs opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:outline-hidden disabled:pointer-events-none data-[state=open]:bg-accent data-[state=open]:text-muted-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4"
          >
            <XIcon />
            <span className="sr-only">Close</span>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </DialogPortal>
  )
}

function DialogHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="dialog-header"
      className={cn('flex flex-col gap-2 text-center sm:text-left', className)}
      {...props}
    />
  )
}

function DialogFooter({
  className,
  showCloseButton = false,
  children,
  ...props
}: React.ComponentProps<'div'> & {
  showCloseButton?: boolean
}) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn('flex flex-col-reverse gap-2 sm:flex-row sm:justify-end', className)}
      {...props}
    >
      {children}
      {showCloseButton && (
        <DialogPrimitive.Close asChild>
          <Button variant="outline">Close</Button>
        </DialogPrimitive.Close>
      )}
    </div>
  )
}

function DialogTitle({ className, ...props }: React.ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn('text-lg leading-none font-semibold', className)}
      {...props}
    />
  )
}

function DialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn('text-sm text-muted-foreground', className)}
      {...props}
    />
  )
}

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
}

import { contrastForeground } from '@/lib/contrast'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { Direction } from 'radix-ui'
export interface UIConfig {
  density: 'comfortable' | 'compact'
  direction: 'ltr' | 'rtl'
  locale: string
}
const ConfigContext = React.createContext<UIConfig>({
  density: 'comfortable',
  direction: 'ltr',
  locale: 'en-US',
})
const PortalContext = React.createContext<HTMLElement | null>(null)
export const usePortalContainer = () => React.useContext(PortalContext) ?? undefined
export const useUIConfig = () => React.useContext(ConfigContext)
export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
  density?: UIConfig['density']
  direction?: UIConfig['direction']
  locale?: string
  accent?: string
  radius?: number
}
export function ConfigProvider({
  density: providedDensity,
  direction: providedDirection,
  locale: providedLocale,
  accent,
  radius,
  children,
  style,
  className,
  ...props
}: ConfigProviderProps) {
  const parent = useUIConfig(),
    density = providedDensity ?? parent.density,
    direction = providedDirection ?? parent.direction,
    locale = providedLocale ?? parent.locale
  const [portal, setPortal] = React.useState<HTMLDivElement | null>(null)
  return (
    <ConfigContext.Provider value={{ density, direction, locale }}>
      <PortalContext.Provider value={portal}>
        <Direction.Provider dir={direction}>
          <div
            dir={direction}
            lang={locale}
            data-density={density}
            className={cn('ergon-root', className)}
            style={
              {
                '--ergon-control-height': density === 'compact' ? '30px' : '2.25rem',
                '--ergon-control-py': density === 'compact' ? '0.25rem' : '0.5rem',
                ...(accent
                  ? {
                      '--primary': accent,
                      '--ring': accent,
                      '--primary-foreground': contrastForeground(accent),
                    }
                  : {}),
                ...(radius !== undefined ? { '--radius': `${radius}px` } : {}),
                ...style,
              } as React.CSSProperties
            }
            {...props}
          >
            {children}
            <div ref={setPortal} data-ergon-portals="" style={{ display: 'contents' }} />
          </div>
        </Direction.Provider>
      </PortalContext.Provider>
    </ConfigContext.Provider>
  )
}

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { Slot } from 'radix-ui'
import { Loader2 } from 'lucide-react'

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        destructive:
          'bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40',
        outline:
          'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        link: 'text-primary underline-offset-4 hover:underline',
        soft: 'bg-primary/10 text-primary hover:bg-primary/15',
        success: 'bg-emerald-600 text-white hover:bg-emerald-700',
        warning: 'bg-amber-400 text-amber-950 hover:bg-amber-500',
        dashed:
          'border border-dashed bg-background text-foreground hover:border-primary hover:text-primary',
      },
      size: {
        default:
          'h-[var(--ergon-control-height,2.25rem)] px-4 py-[var(--ergon-control-py,0.5rem)] has-[>svg]:px-3',
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-xs': "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

/**
 * Composes button variants, loading state, and optional slot rendering. Compact-density styles travel with the installed source.
 */
function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size }), className)}
      aria-busy={loading || undefined}
      {...props}
      disabled={props.disabled || loading}
    >
      {asChild ? (
        children
      ) : (
        <>
          {loading && <Loader2 className="animate-spin" />}
          {children}
        </>
      )}
    </Comp>
  )
}

export { Button, buttonVariants }
